import type { FC } from 'react';
import { useMemo, useRef } from 'react';
import type QRCodeStyling from 'qr-code-styling';
import ToolLayout from '@/components/tools/ToolLayout';
import PillGroup from '@/components/tools/PillGroup';
import QuickStyles from '@/components/tools/qr-generator/QuickStyles';
import ContentForm from '@/components/tools/qr-generator/ContentForm';
import QrPreview from '@/components/tools/qr-generator/QrPreview';
import StylePanels from '@/components/tools/qr-generator/StylePanels';
import ExportBar from '@/components/tools/qr-generator/ExportBar';
import { useDebouncedValue } from '@/hooks/useDebouncedValue';
import { usePersistentState } from '@/hooks/usePersistentState';
import { buildQrPayload } from '@/lib/qr/payload';
import { DEFAULT_QR_FIELDS, QR_CONTENT_TYPES, type QrContentType, type QrFieldsMap } from '@/lib/qr/types';
import { DEFAULT_QR_STYLE, type QrPreset, type QrStyleState } from '@/lib/qr/style';

const QrGenerator: FC = () => {
  const [contentType, setContentType] = usePersistentState<QrContentType>('qr-generator:contentType', 'url');
  const [fields, setFields] = usePersistentState<QrFieldsMap>('qr-generator:fields', DEFAULT_QR_FIELDS);
  const [style, setStyle] = usePersistentState<QrStyleState>('qr-generator:style', DEFAULT_QR_STYLE);
  const qrRef = useRef<QRCodeStyling | null>(null);

  const updateFields = (patch: Partial<QrFieldsMap[QrContentType]>) => {
    setFields((prev) => ({ ...prev, [contentType]: { ...prev[contentType], ...patch } }));
  };

  const updateStyle = (patch: Partial<QrStyleState>) => {
    setStyle((prev) => ({ ...prev, ...patch }));
  };

  const applyPreset = (preset: QrPreset) => {
    setStyle((prev) => ({
      ...prev,
      dotsType: preset.dotsType,
      cornersSquareType: preset.cornersSquareType,
      cornersDotType: preset.cornersDotType,
      fgColor: preset.fgColor,
      bgColor: preset.bgColor,
    }));
  };

  const payload = useMemo(() => buildQrPayload(contentType, fields[contentType]), [contentType, fields]);
  // Redrawing the styled QR (SVG rebuild) on every keystroke/slider tick is
  // more work than the color converter's plain math — debounce the expensive
  // render input while the form/sliders themselves stay fully responsive.
  const debouncedPayload = useDebouncedValue(payload, 150);
  const debouncedStyle = useDebouncedValue(style, 150);
  const hasContent = debouncedPayload.trim().length > 0;

  return (
    <ToolLayout
      title="QR Code Generator"
      description="Create styled QR codes for URLs, text, WiFi, contacts, and more — then export as PNG or SVG."
    >
      <div className="grid grid-cols-1 lg:grid-cols-[1fr,1.2fr] gap-8">
        {/* self-start (not the grid container's items-start) is what lets this
            column stay pinned for the full height of its taller sibling — the
            container keeps its default stretch so the sticky containing block
            spans the whole row, self-start just stops this column's own
            content from stretching to match. */}
        <div className="space-y-6 lg:sticky lg:top-24 lg:self-start">
          <QrPreview data={debouncedPayload} style={debouncedStyle} qrRef={qrRef} />

          <div>
            <h2 className="text-sm font-medium text-muted-foreground mb-3">Quick Styles</h2>
            <QuickStyles style={style} onApply={applyPreset} />
          </div>

          <div>
            <h2 className="text-sm font-medium text-muted-foreground mb-3">Export</h2>
            <ExportBar qrRef={qrRef} disabled={!hasContent} />
          </div>
        </div>

        <div className="glass-panel hover:border-border p-6 md:p-8 space-y-6">
          <div>
            <h2 className="text-sm font-medium text-muted-foreground mb-3">Content Type</h2>
            <PillGroup
              aria-label="QR content type"
              options={QR_CONTENT_TYPES}
              value={contentType}
              onChange={setContentType}
            />
          </div>

          <ContentForm type={contentType} value={fields[contentType]} onChange={updateFields} />

          <div className="pt-2 border-t border-border">
            <StylePanels style={style} onChange={updateStyle} />
          </div>
        </div>
      </div>
    </ToolLayout>
  );
};

export default QrGenerator;
