import type { FC } from 'react';
import { useRef } from 'react';
import { toast } from 'sonner';
import { X, Upload } from 'lucide-react';
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@/components/ui/accordion';
import { Slider } from '@/components/ui/slider';
import { Switch } from '@/components/ui/switch';
import {
  CORNER_DOT_TYPE_OPTIONS,
  CORNER_SQUARE_TYPE_OPTIONS,
  DOT_TYPE_OPTIONS,
  ERROR_CORRECTION_OPTIONS,
  type QrStyleState,
} from '@/lib/qr/style';
import PillGroup from '@/components/tools/PillGroup';
import ColorField from '@/components/tools/ColorField';

interface StylePanelsProps {
  style: QrStyleState;
  onChange: (patch: Partial<QrStyleState>) => void;
}

const MAX_LOGO_BYTES = 2 * 1024 * 1024;

const StylePanels: FC<StylePanelsProps> = ({ style, onChange }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleLogoSelect = (file: File | undefined) => {
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast.error('Please choose an image file');
      return;
    }
    if (file.size > MAX_LOGO_BYTES) {
      toast.error('Image is too large (max 2MB)');
      return;
    }
    const reader = new FileReader();
    reader.onload = () => onChange({ imageDataUrl: reader.result as string });
    reader.readAsDataURL(file);
  };

  return (
    <Accordion type="multiple" defaultValue={['basics']} className="w-full">
      <AccordionItem value="basics">
        <AccordionTrigger className="text-base">Basics</AccordionTrigger>
        <AccordionContent className="space-y-6">
          <div>
            <label className="block text-xs font-medium text-muted-foreground mb-2">
              Size: {style.size}px
            </label>
            <Slider
              aria-label="Size"
              value={[style.size]}
              min={128}
              max={512}
              step={8}
              onValueChange={([v]) => onChange({ size: v })}
            />
          </div>

          <div>
            <label className="block text-xs font-medium text-muted-foreground mb-2">
              Padding: {style.margin}px
            </label>
            <Slider
              aria-label="Padding"
              value={[style.margin]}
              min={0}
              max={40}
              step={2}
              onValueChange={([v]) => onChange({ margin: v })}
            />
          </div>

          <div>
            <label className="block text-xs font-medium text-muted-foreground mb-2">Error Correction</label>
            <PillGroup
              aria-label="Error correction level"
              options={ERROR_CORRECTION_OPTIONS}
              value={style.errorCorrectionLevel}
              onChange={(errorCorrectionLevel) => onChange({ errorCorrectionLevel })}
            />
          </div>
        </AccordionContent>
      </AccordionItem>

      <AccordionItem value="colours">
        <AccordionTrigger className="text-base">Colours</AccordionTrigger>
        <AccordionContent className="space-y-4">
          <ColorField label="Foreground" value={style.fgColor} onChange={(fgColor) => onChange({ fgColor })} />
          <ColorField label="Background" value={style.bgColor} onChange={(bgColor) => onChange({ bgColor })} />
        </AccordionContent>
      </AccordionItem>

      <AccordionItem value="shapes">
        <AccordionTrigger className="text-base">Shapes</AccordionTrigger>
        <AccordionContent className="space-y-5">
          <div>
            <label className="block text-xs font-medium text-muted-foreground mb-2">Bit Style</label>
            <PillGroup
              aria-label="Dot style"
              options={DOT_TYPE_OPTIONS}
              value={style.dotsType}
              onChange={(dotsType) => onChange({ dotsType })}
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-muted-foreground mb-2">Eyes</label>
            <PillGroup
              aria-label="Corner square (eyes) style"
              options={CORNER_SQUARE_TYPE_OPTIONS}
              value={style.cornersSquareType}
              onChange={(cornersSquareType) => onChange({ cornersSquareType })}
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-muted-foreground mb-2">Pupils</label>
            <PillGroup
              aria-label="Corner dot (pupils) style"
              options={CORNER_DOT_TYPE_OPTIONS}
              value={style.cornersDotType}
              onChange={(cornersDotType) => onChange({ cornersDotType })}
            />
          </div>
        </AccordionContent>
      </AccordionItem>

      <AccordionItem value="logo" className="border-b-0">
        <AccordionTrigger className="text-base">Logo / Image</AccordionTrigger>
        <AccordionContent className="space-y-5">
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            className="hidden"
            onChange={(e) => handleLogoSelect(e.target.files?.[0])}
          />

          {style.imageDataUrl ? (
            <div className="flex items-center gap-3">
              <img
                src={style.imageDataUrl}
                alt="Logo preview"
                className="w-12 h-12 rounded-md object-contain border border-border bg-background/50"
              />
              <button
                type="button"
                onClick={() => onChange({ imageDataUrl: null })}
                className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-medium border border-border text-foreground/70 hover:text-foreground hover:border-accent/40 transition-colors"
              >
                <X className="w-3.5 h-3.5" />
                Remove
              </button>
            </div>
          ) : (
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-sm font-medium border border-border bg-background/40 text-foreground/70 hover:text-foreground hover:border-accent/40 transition-colors"
            >
              <Upload className="w-3.5 h-3.5" />
              Upload logo
            </button>
          )}

          {style.imageDataUrl && (
            <>
              <div>
                <label className="block text-xs font-medium text-muted-foreground mb-2">
                  Logo size: {Math.round(style.imageSize * 100)}%
                </label>
                <Slider
                  aria-label="Logo size"
                  value={[style.imageSize]}
                  min={0.1}
                  max={0.6}
                  step={0.05}
                  onValueChange={([v]) => onChange({ imageSize: v })}
                />
              </div>
              <div className="flex items-center justify-between">
                <label className="text-sm text-foreground/80">Hide dots behind logo</label>
                <Switch
                  checked={style.hideBackgroundDots}
                  onCheckedChange={(hideBackgroundDots) => onChange({ hideBackgroundDots })}
                />
              </div>
            </>
          )}
        </AccordionContent>
      </AccordionItem>
    </Accordion>
  );
};

export default StylePanels;
