import type { QrContentType, QrFieldsMap } from './types';

// WiFi QR payloads escape backslash, semicolon, comma, and colon inside
// each field (see the de-facto WIFI: URI format most scanners implement).
function escapeWifiField(value: string): string {
  return value.replace(/([\\;,:])/g, '\\$1');
}

function buildQueryString(params: Record<string, string>): string {
  const entries = Object.entries(params).filter(([, v]) => v.trim().length > 0);
  if (entries.length === 0) return '';
  return `?${entries.map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&')}`;
}

/** Whether the current field values contain enough to produce a meaningful QR code. */
export function hasMinimumContent<T extends QrContentType>(type: T, fields: QrFieldsMap[T]): boolean {
  switch (type) {
    case 'url':
      return (fields as QrFieldsMap['url']).url.trim().length > 0;
    case 'text':
      return (fields as QrFieldsMap['text']).text.trim().length > 0;
    case 'email':
      return (fields as QrFieldsMap['email']).to.trim().length > 0;
    case 'phone':
      return (fields as QrFieldsMap['phone']).phone.trim().length > 0;
    case 'sms':
      return (fields as QrFieldsMap['sms']).phone.trim().length > 0;
    case 'wifi':
      return (fields as QrFieldsMap['wifi']).ssid.trim().length > 0;
    case 'geo': {
      const v = fields as QrFieldsMap['geo'];
      return v.lat.trim().length > 0 && v.lng.trim().length > 0;
    }
    default:
      return false;
  }
}

/** Builds the raw string encoded into the QR code for the given content type. */
export function buildQrPayload<T extends QrContentType>(type: T, fields: QrFieldsMap[T]): string {
  if (!hasMinimumContent(type, fields)) return '';

  switch (type) {
    case 'url': {
      const raw = (fields as QrFieldsMap['url']).url.trim();
      return /^[a-z][a-z0-9+.-]*:/i.test(raw) ? raw : `https://${raw}`;
    }
    case 'text':
      return (fields as QrFieldsMap['text']).text;
    case 'email': {
      const v = fields as QrFieldsMap['email'];
      return `mailto:${v.to.trim()}${buildQueryString({ subject: v.subject, body: v.body })}`;
    }
    case 'phone':
      return `tel:${(fields as QrFieldsMap['phone']).phone.trim()}`;
    case 'sms': {
      const v = fields as QrFieldsMap['sms'];
      return `sms:${v.phone.trim()}${buildQueryString({ body: v.message })}`;
    }
    case 'wifi': {
      const v = fields as QrFieldsMap['wifi'];
      const security = v.encryption === 'nopass' ? 'nopass' : v.encryption;
      const password = v.encryption === 'nopass' ? '' : escapeWifiField(v.password);
      return `WIFI:T:${security};S:${escapeWifiField(v.ssid)};P:${password};H:${v.hidden ? 'true' : 'false'};;`;
    }
    case 'geo': {
      const v = fields as QrFieldsMap['geo'];
      return `geo:${v.lat.trim()},${v.lng.trim()}`;
    }
    default:
      return '';
  }
}
